'use strict'

import resource from '../resource'
import { SPRITE_TEXT_PREFIX, SPRITE_TEXT_WIDTH, SPRITE_TEXT_HEIGHT } from '../constant'

export default {
  draw: function (context, text, color, x, y, width, height, alignement, maxLength) {
    const maxNbLines = Math.floor(height / SPRITE_TEXT_HEIGHT)
    const lines = this.splitTextIntoLines(text, width)
    maxLength = maxLength === undefined ? text.length : maxLength
    maxLength -= (lines.length - 1)
    if (text === "x") {
      console.log(`${x} ${y} ${width} ${height}`)
    }
    let nbDisplayedCharacters = 0
    for (let i = 0; i < lines.length; i++) {
      const alignedLine = this.alignLine(lines[i], width, alignement)
      const displayedLine = alignedLine.substring(0, maxLength + this.getSpacesLeft(lines[i], width) - nbDisplayedCharacters)
      nbDisplayedCharacters += alignedLine.length
      this.drawLine(context, displayedLine, color, x, y)
      y += SPRITE_TEXT_HEIGHT
      if ((i + 1) >= maxNbLines) {
        break
      }
    }
  },

  drawLine: function (context, text, color, x, y) {
    for (const char of text) {
      const sprite = resource.getSprite(`${SPRITE_TEXT_PREFIX}_${color}_${char.toLowerCase()}`)
      if (sprite) {
        sprite.draw(context, x, y, SPRITE_TEXT_WIDTH, SPRITE_TEXT_HEIGHT)
      }
      x += SPRITE_TEXT_WIDTH
    }
  },

  splitTextIntoLines: function (text, maxWidth) {
    const textPerLine = []
    const nbLettersPerLine = Math.floor(maxWidth / SPRITE_TEXT_WIDTH)
    let currentLine = ''
    const parts = text.split(' ')
    for (const part of parts) {
      let currentNbLetters = currentLine.length
      if (currentNbLetters > 0) {
        currentNbLetters += 1 // Count space
      }
      if (currentNbLetters + part.length <= nbLettersPerLine) {
        currentLine += currentNbLetters > 0 ? ` ${part}` : `${part}`
      } else {
        textPerLine.push(currentLine)
        currentLine = `${part}`
      }
    }
    if (currentLine.length > 0) {
      textPerLine.push(currentLine)
    }
    return textPerLine
  },

  getSpacesLeft: function (text, maxWidth) {
    const nbLettersPerLine = Math.floor(maxWidth / SPRITE_TEXT_WIDTH)
    return nbLettersPerLine - text.length
  },

  alignLine: function (text, maxWidth, alignement = 'middle') {
    const spacesLeft = this.getSpacesLeft(text, maxWidth)
    let nbStartSpaces
    let nbEndSpaces
    if (alignement === 'middle') {
      nbStartSpaces = Math.ceil(spacesLeft / 2)
      nbEndSpaces = Math.floor(spacesLeft / 2)
    }
    if (alignement === 'right') {
      nbStartSpaces = spacesLeft
      nbEndSpaces = 0
    }
    if (alignement === 'left') {
      nbStartSpaces = 0
      nbEndSpaces = spacesLeft
    }
    text = text.padStart(text.length + nbStartSpaces, ' ')
    text = text.padEnd(text.length + nbEndSpaces, ' ')
    return text
  }
}
